        <div className="ml-[46px]">
          <ErrorBanner
            message={`Couldn't propose — ${errorMessage(proposeMutation.error, "something went wrong.")}`}
            onRetry={() => proposeMutation.mutate({ requirementId, crewId: candidate.crew_id })}
          />
        </div>
      )}
    </div>
  );
}

