8	import { formatDate, formatDateRange } from "../lib/format";
9	
10	function errorMessage(error: unknown, fallback: string): string {
11	  return error instanceof ApiError ? error.message : fallback;
12	}
13	
14	// proposed needs a decision first, then confirmed, then declined history last.
15	const STATUS_ORDER: Record<AssignmentStatus, number> = { proposed: 0, confirmed: 1, declined: 2 };
16	
17	interface RespondVars {
18	  assignmentId: number;
19	  action: "accept" | "decline";
20	}
