24	
25	  const assignmentsQuery = useQuery({ queryKey: ["assignments"], queryFn: api.assignment.list });
26	  const assignments = useMemo(
27	    () => [...(assignmentsQuery.data ?? [])].sort((a, b) => STATUS_ORDER[a.status] - STATUS_ORDER[b.status]),
28	    [assignmentsQuery.data],
29	  );
30	
31	  const missionIds = useMemo(() => Array.from(new Set(assignments.map((a) => a.mission_id))), [assignments]);
32	
33	  const missionQueries = useQueries({
34	    queries: missionIds.map((id) => ({
35	      queryKey: ["mission", id],
36	      queryFn: () => api.mission.get(id),
37	      enabled: assignmentsQuery.isSuccess,
38	    })),
39	  });
40	  const missionById = new Map<number, MissionDetail>();
41	  missionQueries.forEach((q, i) => {
42	    if (q.data) missionById.set(missionIds[i]!, q.data);
43	  });
44	  const missionsLoading = missionQueries.some((q) => q.isPending);
45	
46	  const respondMutation = useMutation({
47	    mutationFn: (vars: RespondVars) => api.assignment.respond(vars.assignmentId, vars.action),
48	    onMutate: async (vars) => {
49	      await queryClient.cancelQueries({ queryKey: ["assignments"] });
50	      const previous = queryClient.getQueryData<Assignment[]>(["assignments"]);
51	      queryClient.setQueryData<Assignment[]>(["assignments"], (old) =>
52	        (old ?? []).map((a) =>
53	          a.id === vars.assignmentId
54	            ? { ...a, status: vars.action === "accept" ? "confirmed" : "declined", responded_at: new Date().toISOString() }
55	            : a,
56	        ),
57	      );
58	      return { previous };
59	    },
60	    onError: (_err, _vars, context) => {
61	      if (context?.previous) queryClient.setQueryData(["assignments"], context.previous);
62	    },
63	    onSettled: () => queryClient.invalidateQueries({ queryKey: ["assignments"] }),
64	  });
65	
66	  return (
67	    <div className="flex flex-1 flex-col gap-5 overflow-y-auto px-10 py-8">
68	      <div>
69	        <div className="text-[22px] font-bold">My Assignments</div>
70	        <div className="mt-0.5 text-[13px] text-text-2">Missions you've been proposed or confirmed for.</div>
71	      </div>
72	
73	      {assignmentsQuery.isError && (
74	        <ErrorBanner
75	          message={errorMessage(assignmentsQuery.error, "Couldn't load your assignments.")}
76	          onRetry={() => assignmentsQuery.refetch()}
77	        />
78	      )}
79	
80	      {assignmentsQuery.isPending && (
81	        <div className="flex flex-col gap-3">
82	          {[0, 1, 2].map((i) => (
83	            <div key={i} className="h-20 animate-pulse rounded-[10px] border border-border bg-surface" />
84	          ))}
85	        </div>
86	      )}
87	
88	      {assignmentsQuery.isSuccess && assignments.length === 0 && (
89	        <div className="rounded-[10px] border border-border bg-surface px-5 py-10 text-center text-sm text-text-3">
90	          You haven't been proposed for any missions yet.
91	        </div>
92	      )}
93	
